from collections import deque

def find_max_wires_to_cut(n, p, x, q, y):
    prefix_sum = [0] * (n + 1)
    graph_credit = 0

    for i in range(n):
        prefix_sum[x[i]] += 1

    for i in range(1, n):
        graph_credit += prefix_sum[i] - prefix_sum[i - 1]

    s = deque()
    credit = 0
    for i in range(1, n - 1):
        credit += min(p[i] - 1, x[i])
        credit, s[i] = credit - min(p[i] - 1, q[i]), credit - p[i]

    return graph_credit - credit + max(credit, 0)
