def modulo_pow(base, exp, mod):
    result = 1
    while exp > 0:
        if exp % 2 == 1:
            result = (result * base) % mod
        exp = exp >> 1
        base = (base * base) % mod
    return result

def count_binary_numbers(c00, c01, c10, c11, A, B):
    mod = 10**9 + 7
    dp = [[0] * 4 for _ in range(len(str(A)) + 1)]
    dp[0][0], dp[0][1], dp[0][2], dp[0][3] = c00, c01, c10, c11

    for i in range(len(str(A))):
        dp1 = [[0] * 4 for _ in range(len(str(A)) + 1)]
        for j in range(len(str(A)) + 1):
            for k in range(4):
                if j:
                    dp1[j][k] = (dp1[j][k] + dp[j - 1][k]) % mod
                dp1[j][k] = (dp1[j][k] + dp[j][j - 1][k]) % mod
                dp1[j][k] = (dp1[j][k] + dp1[j - 1][k - 1] * (B - A + 1) % mod) % mod
                if k:
                    dp1[j][k] = (dp1[j][k] - dp1[j][k - 1] + mod) % mod
            for l in range(4):
                dp[j][l] = dp1[j][l]
                dp[j][l] = (dp[j][l] + dp[j - 1][l]) % mod
                dp[j][l] = (dp[j][l] + dp1[j][l]) % mod
                dp[j][l] = (dp[j][l] - dp[j - 1][l - 1] + mod) % mod
    count = 0
    for j in range(1, len(str(A)) + 1):
        count = (count + dp[len(str(B))][0]) % mod
    return count

