from collections import defaultdict
from math import factorial

def calculate_ways(total_students, max_throws):
    cache = defaultdict(int)
    cache[1, 1] = 1  # (initial order, allow_max_throws)

    for i in range(2, total_students + 1):
        for allow_max_throws in range(1, i + 1):
            for remove_max_throws in range(0, min(allow_max_throws, i)):
                remain_students = i - remove_max_throws
                coins_worth = (factorial(remain_students - remove_max_throws) * \
                               factorial(total_students - allow_max_throws)) % 1000000007

                if (remains, allow_max_throws) in cache:
                    cache[(i, allow_max_throws)] += remains * coins_worth * 2 
                else:
                    cache[(i, allow_max_throws)] = remains * coins_worth * 2

    return cache[(total_students, max_throws)] % 1000000007

