def factorial(n):
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result

def binomial_coefficient(n, k):
    return factorial(n) // (factorial(k) * factorial(n - k))

def apply_queries(nums, queries):
    n = len(nums)
    for l, r, k in queries:
        for i in range(l - 1, r):
            nums[i] += binomial_coefficient(n, k)
        nums[l - 1] += binomial_coefficient(n - r + l - 2, k - 1)
    nums = [num % 1000000007 for num in nums]
    return nums

