    while from_vertex < len(edges):
        if edges[from_vertex] != 0:
            break
        from_vertex += 1
    return edges[from_vertex], graph[from_vertex] == 0

def calculate_reachability(graph, vertices, from_vertex, edges):
    reachability = {i: 0 for i in range(1, vertices)}
    queue = deque([(from_vertex, 0)])
    reachability[from_vertex] = 0

    while queue:
        current_vertex, steps = queue.popleft()
        for next_vertex in range(1, vertices):
            if graph[next_vertex] > 0 and edges[current_vertex] < graph[next_vertex]:
                edges[current_vertex] += 1
                edges[next_vertex] -= 1
                queue.append((next_vertex, steps + 1))
                reachability[next_vertex] = steps + 1

