                outcome = "Second"

            if (i, j) in visited or outcome != "Draw":
                continue

            visited[(i, j)] = True

            for k in range(1, k+1):
                if game_possible(i, j, k, n, m, fields):
                    winner = game_to_win(i, j, k, n, m, fields)
                    if winner == "second":
                        outcome = "Second"
                        break

                if outcome != "Draw":
                    break

