import random

# Define a class to manage the seniorious carillon
class SenioriousCarillon:
    def __init__(self, n, m):
        self.n = n
        self.m = m
        self.a = [random.randint(1, 1000000)]
        self.age = 500
        self.seed = 123456789
        self.max_value = 1000000

    def roll(self, l, r, x):
        roll = 0
        for i in range(l, r+1):
            roll = (roll * (x + self.age) + (self.a[i] + self.age)) % self.max_value
        return (roll, (x + self.age) * self.age % self.max_value)

    def pick(self, l, r, x):
        return self.age * ((self.age << x) + random.randint(0, (self.n - r) << x)) % self.max_value

    def sieve(self, l, r, x):
        a = [0] * self.n
        for i in range(l, r+1):
            a[i] = random.randint(1, self.max_value)
        a[l-1] = (random.randint(1, self.max_value) + (self.seed * (2**49 * len(a) + x)) % self.max_value) % self.max_value
        return a, (self.seed + (-a[l-1] + (self.seed * (2**49 * len(a) + x)) % self.max_value)) % self.max_value

    def handle(self, op, l, r, x):
        if op == 1:
            for i in range(l, r+1):
                self.a[i] = (self.a[i] + x) % self.max_value
        elif op == 2:
            for i in range(l, r+1):
                self.a[i] = x
        elif op == 3:
            _, x_th_smallest = self.roll(l, r, x)
            if x % 2:
                self.a[l-1] = x % self.max_value
                self.age = (x + self.age) % self.max_value
            return x_th_smallest
        elif op == 4:
            sum_x_power = 0
            for b in self.a[l-1:r+1]:
                sum_x_power = (sum_x_power + (b ** (x + self.age))) % self.max_value
            self.seed = (self.seed + (-sum_x_power + (self.seed * (2**49 * len(self.a[l-1:r+1]) + x)) % self.max_value)) % self.max_value

# Create the seniorious carillon and process the given operations
if __name__ == "__main__":
    carillon = SenioriousCarillon(10, 10)
    operations = [1, 3, 4, 2, 5, 7, 1, 4, 6, 8]
    operations = [2] + [(3, l, r, x) for l, r, x in zip(operations[1:], operations[2:], operations[3:])] + operations[4:]
    for op, l, r, x in operations:
        carillon.handle(op, l, r, x)
        print(carillon.age)
