from collections import defaultdict, deque

def bfs(graph, start, blue_history):
    visited = set([start])
    queue = deque([start])
    depth = 0

    while queue:
        for _ in range(len(queue)):
            node = queue.popleft()
            for neighbor in graph[node]:
                if neighbor in visited:
                    continue
                if blue_history[node] == "B":
                    if neighbor == blue_history.index("R"):
                        continue
                if blue_history[blue_history.index("B"):] in graph[node]:
                    break
                visited.add(neighbor)
                depth += 1
                queue.append(neighbor)
        else:
            break

    return depth

