import sys

def digit_list(n):
    hex_digits = '0123456789abcdef'
    digits = []
    while n > 0:
        digits.append(hex_digits[n % 16])
        n //= 16
    return digits[::-1]

def decode_hex(hex_str):
    hex_digits = '0123456789abcdef'
    num = 0
    for i, digit in enumerate(hex_str[::-1]):
        if digit in hex_digits:
            num += int(digit) * (16 ** i)
    return num

def modify_number(num, sum_value):
    return num ^ sum_value

def process_query(l, r):
    l_dec = decode_hex(l)
    r_dec = decode_hex(r)
    digits_l = digit_list(l_dec)
    digits_r = digit_list(r_dec)

    sum_value = 0
    for digit1, digit2 in zip(digits_l, digits_r):
        if digit1 == digit2:
            sum_value += (1 << (15 - len(digits_l)))

    return sum(modify_number(num, sum_value) for num in digits_l)

def main():
    queries = int(sys.stdin.readline().strip())
    for _ in range(queries):
        l, r = sys.stdin.readline().strip().split(' ')
        result = process_query(l, r)
        print(result)

if __name__ == "__main__":
    main()
